import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import React from 'react'

import DateTime from './DateTime'
import FormError from './Form.error'
import FormFinish from './Form.finish'
import {useUploading} from './Form.hooks'
import FormLoader from './Form.loader'
import FormStart from './Form.start'

function Form(): React.ReactNode {
  const [send2JB, setSend2JB] = React.useState<boolean>(false)
  const {onSubmit, status, payload, uploadId, archiveName, zdFields} = useUploading(send2JB)
  const initialization = !status.loading && !status.ready && !status.error
  const [loaderFinished, setLoaderFinished] = React.useState(false)
  const [issueTitle, setIssueTitle] = React.useState('')
  const [issueDescription, setIssueDescription] = React.useState('')
  const [issueDateTime, setIssueDate] = React.useState<Date | null | undefined>(new Date())

  const zendeskUrl = React.useMemo(() => {
    const url = new URL(
      'https://teamcity-support.jetbrains.com/hc/en-us/requests/new?ticket_form_id=66621',
    )
    const completeDescription = `${issueDescription} (uploadId: ${uploadId}, issue at: ${issueDateTime})`
    const formattedCompleteDescription = completeDescription.replace(/\r?\n/g, '%0A')
    url.searchParams.append('subject', issueTitle)
    url.searchParams.append('description', formattedCompleteDescription)

    // eslint-disable-next-line no-console
    console.log(`url:${url.toString()}`)

    const url2 = url.toString().replace(/\+/g, '%20')

    return url2 + zdFields
  }, [issueDateTime, issueDescription, issueTitle, uploadId, zdFields])

  const handleDateChange = (date: Date | null | undefined) => {
    setIssueDate(date)
  }
  const handleDescriptionChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    setIssueDescription(event.target.value)
  }

  const handleTitleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setIssueTitle(event.target.value)
  }

  return (
    <>
      <form
        onSubmit={event => {
          event.preventDefault()
          onSubmit?.(event)
        }}
      >
        {initialization ? <Header>{'Need help?'}</Header> : null}
        <Content>
          {initialization ? <FormStart /> : null}
          {status.loading || (!loaderFinished && !initialization) ? (
            <FormLoader isLoading={status.loading!} onLoaderFinished={setLoaderFinished} />
          ) : null}

          {status.ready && loaderFinished && payload ? (
            <FormFinish
              send2JetBrains={send2JB}
              applicationId={uploadId!}
              archiveName={archiveName!}
            />
          ) : null}
          {status.error && loaderFinished ? <FormError error={payload!} /> : null}

          {!initialization && !loaderFinished ? (
            <>
              <br />
              <Text size={Text.Size.S}>{'When did the issue start/was noticed?'}</Text>
              <br />
              <DateTime onChange={handleDateChange} />
              <br />
              <br />
              <Input
                value={issueTitle}
                label="Issue short summary"
                size={Size.L}
                onInput={handleTitleChange}
              />
              <br />
              <Input
                label="Issue description"
                size={Size.L}
                value={issueDescription}
                onInput={handleDescriptionChange}
                multiline
                height={ControlsHeight.M}
                defaultValue={''}
              />
            </>
          ) : null}
          <br />
        </Content>
        <Panel>
          {initialization ? (
            <>
              <Button
                type="submit"
                onClick={() => {
                  setSend2JB(true)
                }}
                loader={status.loading}
              >
                {'Collect & send to JetBrains'}
              </Button>
              <Button
                type="submit"
                onClick={() => {
                  setSend2JB(false)
                }}
                primary
                loader={status.loading}
              >
                {'Collect & download'}
              </Button>
            </>
          ) : null}

          {status.ready && loaderFinished && payload ? (
            <Button type="button" primary href={zendeskUrl} target="_blank" rel="noreferrer">
              {'Proceed to ZenDesk'}
            </Button>
          ) : null}
        </Panel>
      </form>
    </>
  )
}

export default Form
