/* eslint-disable @typescript-eslint/no-magic-numbers */
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import ProgressBar from '@jetbrains/ring-ui-built/components/progress-bar/progress-bar'
import React from 'react'

type Props = {
  isLoading: boolean
  onLoaderFinished: (finished: boolean) => void
}

function FormLoader2({isLoading, onLoaderFinished}: Props) {
  const [speed, setSpeed] = React.useState(0.005)
  const [value, setValue] = React.useState(0)

  const loadingRef = React.useRef(isLoading)

  React.useEffect(() => {
    if (loadingRef.current && !isLoading) {
      setSpeed(0.05)
    }
  }, [isLoading])

  React.useEffect(() => {
    if (value >= 1 && !isLoading) {
      onLoaderFinished(true)
    }
  }, [isLoading, onLoaderFinished, value])

  React.useEffect(() => {
    let timeout: NodeJS.Timeout | null = null

    const update = () => {
      setValue(prevValue => {
        if (prevValue >= 1) {
          clearTimeout(timeout!)
          return 1
        }
        timeout = setTimeout(update, 500)
        return prevValue + speed
      })
    }

    update()
    return () => {
      clearTimeout(timeout!)
    }
  }, [speed])

  React.useEffect(
    () => () => {
      onLoaderFinished(true)
    },
    [onLoaderFinished],
  )

  return (
    <>
      <Loader message={'Collecting information...'} />
      <div
        style={{
          height: '25px',
          paddingTop: '25px',
        }}
      >
        <ProgressBar
          label="Progress"
          value={value}
          style={{
            width: 400,
          }}
        />
      </div>
    </>
  )
}

export default FormLoader2
