import type {DatePickerAttrs} from '@jetbrains/ring-ui-built/components/date-picker/date-picker'
import DatePicker from '@jetbrains/ring-ui-built/components/date-picker/date-picker'
import {Component} from 'react'

class DateTimePicker extends Component<DatePickerAttrs> {
  date = new Date()

  getProperMonth = () => {
    const monthNames = [
      'January',
      'February',
      'March',
      'April',
      'May',
      'June',
      'July',
      'August',
      'September',
      'October',
      'November',
      'December',
    ]
    return monthNames[this.date.getMonth()]
  }

  // eslint-disable-next-line sort-class-members/sort-class-members
  state = {
    date: `${this.date.getDate()} ${this.getProperMonth()} ${this.date.getFullYear()}, ${this.date.getHours()}:${this.date.getMinutes()}`,
  }

  setDate = (date: string | Date | null | undefined) => {
    this.setState({date})
  }

  render() {
    return (
      <div>
        <DatePicker date={this.state.date} onChange={this.setDate} withTime clear {...this.props} />
      </div>
    )
  }
}

export default DateTimePicker
