import clipboard from '@jetbrains/ring-ui-built/components/clipboard/clipboard'
import Code from '@jetbrains/ring-ui-built/components/code/code'
import Heading from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import React from 'react'

export default function FormFinish({
  send2JetBrains,
  applicationId,
  archiveName,
}: {
  send2JetBrains: boolean
  applicationId: string
  archiveName: string
}): React.ReactElement {
  const copyText = React.useCallback(() => {
    clipboard.copyText(applicationId, 'Text copied!', 'Text copying error')
  }, [applicationId])

  const downloadUrl = `${window.location.origin}/support/download.html?archiveName=${archiveName}`

  const [url, setUrl] = React.useState('')
  const fetchUrl = React.useCallback(async () => {
    const response = await fetch(downloadUrl)
    const blob = await response.blob()
    const resolvedUrl = window.URL.createObjectURL(blob)
    setUrl(resolvedUrl)
  }, [downloadUrl])
  React.useEffect(() => {
    fetchUrl()
  }, [fetchUrl])

  return (
    <>
      <Heading level={Heading.Levels.H1}>{'Logs successfully collected! '}</Heading>

      {!send2JetBrains && (
        <div>
          <br />
          <Text size={Text.Size.M}>
            {'Download the collected information'}
            <a href={url} download={archiveName}>
              {' here'}
            </a>
            {'.'}
          </Text>
        </div>
      )}

      <p>
        <Text size={Text.Size.M}>
          {'You can now open a support request using the button below.'}
        </Text>
      </p>

      {send2JetBrains && (
        <div>
          <Text>
            <b>{'Please mention the following upload ID:'}</b>
          </Text>
          <Code code={applicationId} />
          <p>
            <Link onClick={copyText} pseudo>
              {'Click to copy the Upload ID'}
            </Link>
          </p>
        </div>
      )}
    </>
  )
}
