import utils from '@jetbrains/teamcity-ui/dist/utils'
import React from 'react'

import {generateGUID} from '../../utils/Generic-Utils'
import getStringError from '../../utils/getStringError'
import {
  extractUploadIdFromHtml,
  getArchiveNameFromHtml,
  parseResult4ZendeskCustomFields,
  parseURL,
} from '../../utils/Parsing-Utils'

const defaultState: {
  loading?: boolean
  ready?: boolean
  error?: boolean
  result?: string
  uploadId?: string
  archiveName?: string
  zdFields?: string
  send2JB?: boolean
} = {
  loading: false,
}

export const useUploading = (send2JetBrains: boolean) => {
  const buildData = parseURL()
  const [uploadingState, setUploadingState] = React.useState(defaultState)

  const onSubmit = React.useCallback(
    async (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault()

      try {
        setUploadingState({...defaultState, loading: true})

        const buildId = buildData.buildId
        const buildConfigurationId = buildData.buildConfigurationId
        const projectId = buildData.projectId

        let requestUrl = `support/collect.html?send2JetBrains=${send2JetBrains}`
        const guid = generateGUID()
        requestUrl += `&guid=${guid}`

        if (buildId != null) {
          requestUrl += `&buildId=${buildId}`
        }
        if (buildConfigurationId != null) {
          requestUrl += `${buildId != null ? '&' : ''}buildConfigurationId=${buildConfigurationId}`
        }
        if (projectId != null) {
          requestUrl += `${buildConfigurationId != null ? '&' : ''}projectId=${projectId}`
        }
        const result = await utils.requestText(requestUrl, {
          method: 'POST',
        })

        let uploadId = ''
        let zdFields = ''

        if (send2JetBrains) {
          uploadId = extractUploadIdFromHtml(result)
          zdFields = parseResult4ZendeskCustomFields(result)

          if (uploadId) {
            setUploadingState({...defaultState, ready: true, result, uploadId, zdFields})
          } else {
            setUploadingState({
              ...defaultState,
              result: 'Could not upload!',
              error: true,
            })
          }
        } else {
          //extract file name
          const archiveName = getArchiveNameFromHtml(result)
          zdFields = parseResult4ZendeskCustomFields(result)

          setUploadingState({...defaultState, ready: true, result, uploadId, archiveName, zdFields})
        }
      } catch (error) {
        setUploadingState({
          ...defaultState,
          error: true,
          ready: false,
          result: getStringError(error),
        })
      }
    },
    [buildData.buildConfigurationId, buildData.buildId, buildData.projectId, send2JetBrains],
  )

  const setState = React.useCallback((state: any) => {
    setUploadingState({
      ...defaultState,
      ...state,
    })
  }, [])

  return {
    status: {
      loading: uploadingState.loading,
      ready: uploadingState.ready,
      error: uploadingState.error,
    },
    payload: uploadingState.result,
    uploadId: uploadingState.uploadId,
    archiveName: uploadingState.archiveName,
    zdFields: uploadingState.zdFields,
    send2JetBrains: uploadingState.send2JB,
    setState,
    onSubmit,
  }
}
