import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import React from 'react'

import Form from '../Form/Form'

import styles from './Anchor.module.css'

function Anchor() {
  const [dialogVisible, setDialogVisible] = React.useState<boolean>(false)

  const openDialog = React.useCallback(() => setDialogVisible(true), [setDialogVisible])
  const closeDialog = React.useCallback(() => setDialogVisible(false), [])

  return (
    <div>
      <Button inline onClick={openDialog} className={styles.button}>
        {'Need help?'}
      </Button>
      <Dialog onCloseAttempt={closeDialog} showCloseButton show={dialogVisible}>
        <Form />
      </Dialog>
    </div>
  )
}

export default Anchor
